import SwiftUI
import MeldShared

/// Bridges the Kotlin-provided `UIViewController` (Compose content) into SwiftUI.
/// The facade name `MainViewControllerKt` is generated by Kotlin/Native from
/// `shared/src/iosMain/.../MainViewController.kt`; the member keeps the Kotlin
/// case (`MainViewController()`, per the official Compose Multiplatform iOS
/// template). CI greps it in `MeldShared.h`.
struct ComposeViewController: UIViewControllerRepresentable {
    func makeUIViewController(context: Context) -> UIViewController {
        MainViewControllerKt.MainViewController()
    }

    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {
    }
}

struct ContentView: View {
    var body: some View {
        ComposeViewController()
            .ignoresSafeArea()
    }
}
